void PerformancePage::pushInput(){if(updating)return;auto&c=engine.getInputLoadingControl();c.enabled.store(inputEnabled.getToggleState());c.pickupResistanceOhm.store((float)pickupR.getValue()*1000);c.pickupInductanceH.store((float)pickupL.getValue());c.cableCapacitancePf.store((float)cableC.getValue());c.inputImpedanceOhm.store((float)inputZ.getValue()*1000);c.trimDb.store((float)inputTrim.getValue());}
void PerformancePage::pushPitch(){if(updating)return;auto&c=engine.getExpressionPitchControl();int m=(pitchMain.getToggleState()?1:0)|(pitchClean.getToggleState()?2:0)|(pitchSub.getToggleState()?4:0);if(!m)m=1;c.enabled.store(pitchEnabled.getToggleState());c.routeMask.store(m);c.semitones.store((float)pitchSemitones.getValue());c.expression.store((float)pitchExpression.getValue());c.wet.store((float)pitchWet.getValue());c.dry.store((float)pitchDry.getValue());c.tracking.store((float)pitchTracking.getValue());c.tone.store((float)pitchTone.getValue());c.smooth.store((float)pitchSmooth.getValue());}
void PerformancePage::pushRigDetail(){if(updating)return;auto&c=engine.getHQEffectsRack().parallelRigControl();c.enabled.store(rigEnabled.getToggleState());c.autoLatencyComp.store(autoLatency.getToggleState());c.mainLevelDb.store((float)mainLevel.getValue());c.mainDelayMs.store((float)mainDelay.getValue());c.cleanEnabled.store(cleanEnabled.getToggleState());c.cleanLevelDb.store((float)cleanLevel.getValue());c.cleanHpHz.store((float)cleanHp.getValue());c.cleanLpHz.store((float)cleanLp.getValue());c.cleanPresenceDb.store((float)cleanPresence.getValue());c.cleanDrive.store((float)cleanDrive.getValue());c.cleanBassDb.store((float)cleanBass.getValue());c.cleanMidDb.store((float)cleanMid.getValue());c.cleanTrebleDb.store((float)cleanTreble.getValue());c.cleanDelayMs.store((float)cleanDelay.getValue());c.cleanInvert.store(cleanInvert.getToggleState());c.subEnabled.store(subEnabled.getToggleState());c.subLevelDb.store((float)subLevel.getValue());c.subHpHz.store((float)subHp.getValue());c.subLpHz.store((float)subLp.getValue());c.subBodyDb.store((float)subBody.getValue());c.subDrive.store((float)subDrive.getValue());c.subBassDb.store((float)subBass.getValue());c.subMidDb.store((float)subMid.getValue());c.subTrebleDb.store((float)subTreble.getValue());c.subTracking.store((float)subTracking.getValue());c.subTone.store((float)subTone.getValue());c.subSmooth.store((float)subSmooth.getValue());c.subDelayMs.store((float)subDelay.getValue());c.subInvert.store(subInvert.getToggleState());}
void PerformancePage::pushDualDelay(){if(updating)return;auto&c=engine.getDualDelayControl();c.enabled.store(dualDelayEnabled.getToggleState());c.timeLms.store((float)delayL.getValue());c.timeRms.store((float)delayR.getValue());c.feedbackL.store((float)feedbackL.getValue());c.feedbackR.store((float)feedbackR.getValue());c.crossFeedback.store((float)crossFeedback.getValue());c.mix.store((float)delayMix.getValue());c.lowCutHz.store((float)delayLowCut.getValue());c.highCutHz.store((float)delayHighCut.getValue());c.modRateHz.store((float)delayModRate.getValue());c.modDepthMs.store((float)delayModDepth.getValue());}
void PerformancePage::captureScene(){int n=juce::jlimit(0,7,sceneSelector.getSelectedId()-1);auto&s=engine.getSceneSwitcher().scene(n);auto&r=engine.getHQEffectsRack().parallelRigControl();auto&p=engine.getExpressionPitchControl();auto&d=engine.getDualDelayControl();s.parallelEnabled=r.enabled.load();s.mainDb=r.mainLevelDb.load();s.cleanDb=r.cleanLevelDb.load();s.subDb=r.subLevelDb.load();s.expressionPitchEnabled=p.enabled.load();s.expression=p.expression.load();s.pitchSemitones=p.semitones.load();s.dualDelayEnabled=d.enabled.load();for(int x=0;x<4;++x){auto&q=engine.getHQEffectsRack().pedalSlot(x);s.pedalEnabled[(size_t)x]=q.enabled.load();s.pedalRouteMask[(size_t)x]=q.routeMask.load();}}
void PerformancePage::recallScene(){engine.getSceneSwitcher().request(juce::jlimit(0,7,sceneSelector.getSelectedId()-1));}
void PerformancePage::paint(juce::Graphics&g){g.fillAll(juce::Colour::fromRGB(12,16,21));g.setColour(juce::Colour::fromRGB(28,34,42));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(10),12,1);g.setColour(juce::Colour::fromRGB(150,158,168));g.setFont(9.5f);for(auto*s:{&pickupR,&pickupL,&cableC,&inputZ,&inputTrim,&pitchSemitones,&pitchExpression,&pitchWet,&pitchDry,&pitchTracking,&pitchTone,&pitchSmooth,&mainLevel,&mainDelay,&cleanLevel,&cleanHp,&cleanLp,&cleanPresence,&cleanDrive,&cleanBass,&cleanMid,&cleanTreble,&cleanDelay,&subLevel,&subHp,&subLp,&subBody,&subDrive,&subBass,&subMid,&subTreble,&subTracking,&subTone,&subSmooth,&subDelay,&delayL,&delayR,&feedbackL,&feedbackR,&crossFeedback,&delayMix,&delayLowCut,&delayHighCut,&delayModRate,&delayModDepth})g.drawText(s->getName(),s->getBounds().withHeight(14).translated(0,-10),juce::Justification::centred);}
void PerformancePage::resized(){auto r=getLocalBounds().reduced(18);title.setBounds(r.removeFromTop(32));auto row=[&](juce::Label&l,int h){auto z=r.removeFromTop(h);l.setBounds(z.removeFromTop(18));return z;};auto a=row(inputTitle,82);inputEnabled.setBounds(a.removeFromTop(20).removeFromLeft(120));int w=juce::jmax(68,a.getWidth()/5);for(auto*s:{&pickupR,&pickupL,&cableC,&inputZ,&inputTrim})s->setBounds(a.removeFromLeft(w).reduced(2,4));auto b=row(pitchTitle,88);auto bh=b.removeFromTop(20);pitchEnabled.setBounds(bh.removeFromLeft(100));pitchMain.setBounds(bh.removeFromLeft(65));pitchClean.setBounds(bh.removeFromLeft(70));pitchSub.setBounds(bh.removeFromLeft(60));w=juce::jmax(66,b.getWidth()/7);for(auto*s:{&pitchSemitones,&pitchExpression,&pitchWet,&pitchDry,&pitchTracking,&pitchTone,&pitchSmooth})s->setBounds(b.removeFromLeft(w).reduced(2,4));auto q=row(rigTitle,215);auto qh=q.removeFromTop(20);rigEnabled.setBounds(qh.removeFromLeft(100));cleanEnabled.setBounds(qh.removeFromLeft(70));subEnabled.setBounds(qh.removeFromLeft(60));autoLatency.setBounds(qh.removeFromLeft(115));cleanInvert.setBounds(qh.removeFromLeft(90));subInvert.setBounds(qh.removeFromLeft(80));auto q1=q.removeFromTop(q.getHeight()/2);int n=12;w=juce::jmax(58,q1.getWidth()/n);for(auto*s:{&mainLevel,&mainDelay,&cleanLevel,&cleanHp,&cleanLp,&cleanPresence,&cleanDrive,&cleanBass,&cleanMid,&cleanTreble,&cleanDelay})s->setBounds(q1.removeFromLeft(w).reduced(1,4));w=juce::jmax(58,q.getWidth()/12);for(auto*s:{&subLevel,&subHp,&subLp,&subBody,&subDrive,&subBass,&subMid,&subTreble,&subTracking,&subTone,&subSmooth,&subDelay})s->setBounds(q.removeFromLeft(w).reduced(1,4));auto d=row(delayTitle,88);dualDelayEnabled.setBounds(d.removeFromTop(20).removeFromLeft(115));w=juce::jmax(60,d.getWidth()/10);for(auto*s:{&delayL,&delayR,&feedbackL,&feedbackR,&crossFeedback,&delayMix,&delayLowCut,&delayHighCut,&delayModRate,&delayModDepth})s->setBounds(d.removeFromLeft(w).reduced(1,4));auto s=row(sceneTitle,42);sceneSelector.setBounds(s.removeFromLeft(110).reduced(2));sceneCapture.setBounds(s.removeFromLeft(82).reduced(2));sceneRecall.setBounds(s.removeFromLeft(82).reduced(2));s.removeFromLeft(15);outputMode.setBounds(s.removeFromLeft(260).reduced(2));}
